// QuadMosaic

var nOff = 5;
var pointDensity;
var overAllTexture;
var mySize;
var colors;
var color1, color2, grad;

// colors
const palettes = [
	["#e3d7a3BF", "#f5989d40", "#ea618eBF", "#fce4d6b3", "#caac7180"],
	["#7d483eBF", "#b8764440", "#e6d2c9BF", "#e45e00b3", "#905c4080"],
	["#ff7e6bBF", "#f33e6b40", "#8c5e58BF", "#a9f0d1b3", "#fff7f880"],
	["#70c1b3BF", "#aaf0d340", "#50514fBF", "#ffe066b3", "#247ba080"],
	["#f8f9fbBF", "#f9f6e040", "#45454cBF", "#ef9643b3", "#f0654380"],
	["#3c1642BF", "#38637540", "#086375BF", "#b2ff9eb3", "#1dd3b080"],
	["#deFbE4BF", "#f7f9fb40", "#02906cBF", "#eafc70b3", "#02b08c80"],
	["#6cbbd4BF", "#5863b140", "#5282a1BF", "#fee8f7b3", "#c1f29b80"],
	["#211E20BF", "#41355040", "#14777FBF", "#F6CCA5b3", "#5EB8A580"],
	["#1b1b1bBF", "#29292940", "#f3f3f3BF", "#222222b3", "#ff000080"],
	["#ffffffBF", "#e2e2ec40", "#1e32aaBF", "#0564ffb3", "#82afff80"]
]

const palettes2 = [
	["#e3d7a300", "#f5989d00", "#ea618e00", "#fce4d600", "#caac7100"],
	["#7d483e00", "#b8764400", "#e6d2c900", "#e45e0000", "#905c4000"],
	["#ff7e6b00", "#f33e6b00", "#8c5e5800", "#a9f0d100", "#fff7f800"],
	["#70c1b300", "#aaf0d300", "#50514f00", "#ffe06600", "#247ba000"],
	["#f8f9fb00", "#f9f6e000", "#45454c00", "#ef964300", "#f0654300"],
	["#3c164200", "#38637500", "#08637500", "#b2ff9e00", "#1dd3b000"],
	["#deFbE400", "#f7f9fb00", "#02906c00", "#eafc7000", "#02b08c00"],
	["#6cbbd400", "#5863b100", "#5282a100", "#fee8f700", "#c1f29b00"],
	["#211E2000", "#41355000", "#14777F00", "#F6CCA500", "#5EB8A500"],
	["#1b1b1b00", "#29292900", "#f3f3f300", "#22222200", "#ff000000"],
	["#ffffff00", "#e2e2ec00", "#1e32aa00", "#0564ff00", "#82afff00"]
]

//background colors 
const palettesbg = [
	"#ffffff", "#222222"
]

function getRandomInt(min, max) {
	min = Math.ceil(min);
	max = Math.floor(max);
	return Math.floor(Math.random() * (max - min) + min);
}

/** OPC START **/
OPC.slider("seed", getRandomInt(0, 1000), 0, 1000, 1);
OPC.slider("Color_Front", 0, 0, palettes.length - 1, 1);
OPC.slider("Color_Behind", 2, 0, palettes.length - 1, 1);
//OPC.slider("Color_Bg", 1, 0, palettesbg.length - 1, 1);
OPC.slider('density', 28, 10, 50, 2);
OPC.slider('quad_Width', -2.75, -4, 4, 0.25);
OPC.slider('quad_Height', -3, -4, 4, 0.25);
OPC.slider('quad_Slope', 1.5, -3, 3, 0.5);
/** OPC END **/

let palettebg;

function setup() {
	//pseed =seed;
	randomSeed(seed);
	noiseSeed(seed);
	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize);
	// pixelDensity(5);
	background(245);
	//let filter = new makeFilter();
}


function makeFilter() {
	// noiseのフィルターをつくる
	colorMode(HSB, 360, 100, 100, 100);
	drawingContext.shadowColor = color(0, 0, 5, 95);
	overAllTexture = createGraphics(width, height);
	overAllTexture.loadPixels();
	for (var i = 0; i < width; i++) {
		for (var j = 0; j < height; j++) {
			overAllTexture.set(
				i,
				j,
				color(
					0,
					0,
					0,
					noise(i / 3, j / 3, (i * j) / 50) * random(5, 15)
				)
			);
		}
	}
	overAllTexture.updatePixels();
}

function draw() {
	let palette1 = palettes[Color_Behind];
	let palette12 = palettes2[Color_Behind];
	let palette2 = palettes[Color_Front];
	let palette22 = palettes2[Color_Front];
	//palettebg = palettesbg[Color_Bg];
	randomSeed(seed);
	noiseSeed(seed);
	pointDensity = width / density;
	noStroke();
	fill(245);
	rect(0, 0, width, height);

	//nOff = nOff + 1;
	for (let x = -width * 0.1; x < width * 1.1; x += pointDensity * 2) {
		for (let y = -height * 0.1; y < height * 1.1; y += pointDensity * 2) {
			//noFill();
			push();
			translate(x, y);
			//blendMode(BLEND);
			strokeCap(SQUARE);
			strokeWeight(random());

			let quadX = pointDensity * quad_Width;
			let quadY = pointDensity * quad_Height;
			let plusY = quad_Slope * pointDensity;
			let num = noise((x + nOff) / 10, y / 10);
			if (num < 0.15) {
				noStroke();
				fill(0);
				color1 = palette1[int(random(1, 5))];
				color2 = palette12[int(random(1, 5))];
				grad = drawingContext.createLinearGradient(0, 0, quadX, quadY);
				grad.addColorStop(0, color1);
				grad.addColorStop(1, color2);
				drawingContext.fillStyle = grad;
			} else if (num >= 0.25 && num < 0.35) {
				noFill();
				strokeWeight(random(1,5));
				stroke(palette1[int(random(1, 5))]);
			} else if (num >= 0.45 && num < 0.7) {
				noStroke();
				fill(0);
				color1 = palette1[int(random(1, 5))];
				color2 = palette12[int(random(1, 5))];
				grad = drawingContext.createLinearGradient(0, 0, quadX, quadY);
				grad.addColorStop(0, color1);
				grad.addColorStop(1, color2);
				drawingContext.fillStyle = grad;
			} else {
				noFill();
				strokeWeight(random(1,3));
				stroke(palette1[int(random(1, 5))]);
			}
			//quad(0, 0, 0, quadY, quadX, quadY-plusY, quadX,  - plusY);
			triangle(0, quadY, -quadX, quadY - plusY, -quadX, -plusY);

			pop();
		}
	}
	//blendMode(LIGHTEST);
	for (let x = -width * 0.1; x < width * 1.1; x += pointDensity * 2) {
		for (let y = -height * 0.1; y < height * 1.1; y += pointDensity * 2) {
			push();
			translate(x, y);
			var num = noise((x + nOff) / 10, y / 10);
			//print(num);
			var quadX = pointDensity * quad_Width;
			var quadY = pointDensity * quad_Height;
			var plusY = quad_Slope * pointDensity;
			if (num < 0.15) {
				noStroke();
				fill(0);
				color1 = palette2[int(random(1, 5))];
				color2 = palette22[int(random(1, 5))];
				grad = drawingContext.createLinearGradient(0, 0, quadX, quadY);
				grad.addColorStop(0, color1);
				grad.addColorStop(1, color2);
				drawingContext.fillStyle = grad;
			} else if (num >= 0.2 && num < 0.35) {
				noStroke();
				fill(0);
				color1 = palette2[int(random(1, 5))];
				color2 = palette22[int(random(1, 5))];
				grad = drawingContext.createLinearGradient(0, 0, quadX, quadY);
				grad.addColorStop(0, color1);
				grad.addColorStop(1, color2);
				drawingContext.fillStyle = grad;
			} else if (num >= 0.45 && num < 0.65) {
				noFill();
				strokeWeight(random(1));
				stroke(palette2[int(random(1, 5))]);
			} else {
				noStroke();
				fill(0);
				color1 = palette2[int(random(1, 5))];
				color2 = palette22[int(random(1, 5))];
				grad = drawingContext.createLinearGradient(0, 0, quadX, quadY);
				grad.addColorStop(0, color1);
				grad.addColorStop(1, color2);
				drawingContext.fillStyle = grad;
			}
			// drawingContext.shadowColor = color(0, 0, 0, 20);
			// drawingContext.shadowOffsetX = 10;
			// drawingContext.shadowOffsetY = 10;
			// drawingContext.shadowBlur = 100;
			triangle( 0, quadY, quadX, quadY - plusY, quadX, -plusY);
			//quad(0, 0, 0, quadY, -quadX, quadY-plusY, -quadX,  - plusY);

			pop();
		}
	}
	//image(overAllTexture, 0, 0);
}

function keyTyped() {
	if (key === "s" || key === "S") {
		saveCanvas("QuadMosaic_2.0", "png");
	}
}

